oxy_webhelp_navlinks = {"data_transfer_mechanisms_oracle-d39307e38460":{"topics":[{"title":"Enabling secure thrift using REST APIs","shortdesc":"<p class=\"shortdesc\">To securely transfer data between the Rubrik cluster and the Oracle host, enable the         secure thrift data transfer mechanism for Oracle databases using Rubrik REST         APIs.<\/p>","href":"oracle\/enabling_secure_thrift_using_rest_apis.html","attributes":{"data-id":"enabling_secure_thrift_using_rest_apis"},"menu":{"hasChildren":false},"tocID":"enabling_secure_thrift_using_rest_apis-d39307e38471","topics":[]},{"title":"Enabling secure thrift using Rubrik GraphQL APIs","shortdesc":"<p class=\"shortdesc\">To securely transfer data between the Rubrik cluster and the Oracle host, enable the         secure thrift data transfer mechanism for Oracle databases using Rubrik GraphQL         APIs.<\/p>","href":"oracle\/enabling_secure_thrift_using_gql.html","attributes":{"data-id":"enabling_secure_thrift_using_gql"},"menu":{"hasChildren":false},"tocID":"enabling_secure_thrift_using_gql-d39307e38482","topics":[]},{"title":"Secure thrift backup parameter recommendations","shortdesc":"<p class=\"shortdesc\">When you are using secure thrift, Rubrik recommends adding parameters to the SPFILE         on your Oracle database to improve performance during backup operations.<\/p>","href":"oracle\/secure_thrift_backup_param.html","attributes":{"data-id":"secure_thrift_backup_param"},"menu":{"hasChildren":false},"tocID":"secure_thrift_backup_param-d39307e38493","topics":[]}]}};